# AI Agents - Derinlemesine

## 🔬 Function Calling Deep Dive

### OpenAI Function Calling

```python
import openai
import json

def get_weather(city: str, unit: str = "celsius"):
    # Gerçek API çağrısı
    return {"temperature": 18, "condition": "sunny", "unit": unit}

def get_stock_price(symbol: str):
    # Gerçek API çağrısı
    return {"symbol": symbol, "price": 150.25}

# Tool definitions (JSON Schema)
tools = [
    {
        "type": "function",
        "function": {
            "name": "get_weather",
            "description": "Get current weather for a city",
            "parameters": {
                "type": "object",
                "properties": {
                    "city": {
                        "type": "string",
                        "description": "City name"
                    },
                    "unit": {
                        "type": "string",
                        "enum": ["celsius", "fahrenheit"],
                        "description": "Temperature unit"
                    }
                },
                "required": ["city"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "get_stock_price",
            "description": "Get current stock price",
            "parameters": {
                "type": "object",
                "properties": {
                    "symbol": {
                        "type": "string",
                        "description": "Stock symbol (e.g., AAPL)"
                    }
                },
                "required": ["symbol"]
            }
        }
    }
]

# Agent loop
def run_agent(user_query):
    messages = [{"role": "user", "content": user_query}]

    while True:
        response = openai.chat.completions.create(
            model="gpt-4-turbo",
            messages=messages,
            tools=tools,
            tool_choice="auto"  # LLM karar verir
        )

        message = response.choices[0].message
        messages.append(message)

        # Finish?
        if message.finish_reason == "stop":
            return message.content

        # Tool calls?
        if message.tool_calls:
            for tool_call in message.tool_calls:
                function_name = tool_call.function.name
                arguments = json.loads(tool_call.function.arguments)

                # Execute function
                if function_name == "get_weather":
                    result = get_weather(**arguments)
                elif function_name == "get_stock_price":
                    result = get_stock_price(**arguments)

                # Add result to messages
                messages.append({
                    "role": "tool",
                    "tool_call_id": tool_call.id,
                    "name": function_name,
                    "content": json.dumps(result)
                })

# Test
result = run_agent(
    "İstanbul'da hava kaç derece ve Apple hissesi ne kadar?"
)
print(result)
```

### Parallel Function Calling

```python
# LLM birden fazla tool'u paralel çağırabilir
user_query = "İstanbul, New York ve Tokyo'da hava nasıl?"

response = openai.chat.completions.create(
    model="gpt-4-turbo",
    messages=[{"role": "user", "content": user_query}],
    tools=tools
)

# LLM 3 tool call önerebilir
for tool_call in response.choices[0].message.tool_calls:
    print(tool_call.function.name, tool_call.function.arguments)
# get_weather {"city": "Istanbul"}
# get_weather {"city": "New York"}
# get_weather {"city": "Tokyo"}

# Paralel çalıştır
import asyncio

async def parallel_execute(tool_calls):
    tasks = []
    for tc in tool_calls:
        func = globals()[tc.function.name]
        args = json.loads(tc.function.arguments)
        tasks.append(func(**args))

    results = await asyncio.gather(*tasks)
    return results
```

## 🧠 ReAct Implementation

```python
class ReActAgent:
    def __init__(self, llm, tools):
        self.llm = llm
        self.tools = {tool.name: tool for tool in tools}
        self.scratchpad = []

    def run(self, task, max_steps=10):
        self.scratchpad = [f"Task: {task}"]

        for step in range(1, max_steps + 1):
            # Prompt with scratchpad
            prompt = self._build_prompt()
            response = self.llm(prompt)

            # Parse response
            if "Thought:" in response:
                thought = self._extract_section(response, "Thought")
                self.scratchpad.append(f"Thought {step}: {thought}")

            if "Action:" in response:
                action_text = self._extract_section(response, "Action")
                action, args = self._parse_action(action_text)
                self.scratchpad.append(f"Action {step}: {action}({args})")

                # Execute action
                try:
                    observation = self.tools[action](args)
                    self.scratchpad.append(f"Observation {step}: {observation}")
                except Exception as e:
                    self.scratchpad.append(f"Observation {step}: Error - {e}")

            if "Answer:" in response:
                answer = self._extract_section(response, "Answer")
                return answer

        return "Max steps reached without answer"

    def _build_prompt(self):
        return f"""
You are a ReAct agent. Follow this format:

Thought: [your reasoning]
Action: [tool_name](arguments)
Observation: [tool result - will be provided]
... (repeat)
Answer: [final answer when ready]

Available tools:
{self._format_tools()}

{chr(10).join(self.scratchpad)}
"""

    def _format_tools(self):
        return "\n".join([
            f"- {name}: {tool.description}"
            for name, tool in self.tools.items()
        ])
```

## 🗺️ Plan-and-Execute Agent

```python
from typing import List

class PlanExecuteAgent:
    def __init__(self, planner_llm, executor_agent):
        self.planner = planner_llm
        self.executor = executor_agent

    def run(self, task):
        # 1. Plan oluştur
        plan = self._create_plan(task)
        print(f"Plan: {plan}")

        # 2. Her adımı sırayla yürüt
        results = []
        for i, step in enumerate(plan):
            print(f"\nExecuting step {i+1}: {step}")
            result = self.executor.run(step)
            results.append(result)
            print(f"Result: {result}")

        # 3. Final sentez
        return self._synthesize(task, plan, results)

    def _create_plan(self, task) -> List[str]:
        prompt = f"""
        Task: {task}

        Create a step-by-step plan to solve this task.
        Each step should be a single, clear action.
        Return as numbered list.
        """

        response = self.planner(prompt)

        # Parse numbered list
        steps = []
        for line in response.split('\n'):
            if re.match(r'^\d+\.', line):
                steps.append(line.split('.', 1)[1].strip())

        return steps

    def _synthesize(self, task, plan, results):
        prompt = f"""
        Original task: {task}

        Plan executed:
        {chr(10).join([f"{i+1}. {s}" for i, s in enumerate(plan)])}

        Results:
        {chr(10).join([f"{i+1}. {r}" for i, r in enumerate(results)])}

        Provide final answer to the original task.
        """

        return self.planner(prompt)

# Kullanım
planner = OpenAI(model="gpt-4")
executor = ReActAgent(llm=planner, tools=[...])

agent = PlanExecuteAgent(planner, executor)
result = agent.run(
    "Find the population of the 3 largest cities in Turkey and calculate the total"
)
```

## 🔄 Agent with Memory

```python
class MemoryAgent:
    def __init__(self, llm, tools, memory_size=5):
        self.llm = llm
        self.tools = tools
        self.short_term_memory = []  # Last N interactions
        self.long_term_memory = []   # Summarized history
        self.memory_size = memory_size

    def run(self, query):
        # Build context with memory
        context = self._build_context(query)

        # Run agent
        result = self._execute_with_tools(context)

        # Store in memory
        self._update_memory(query, result)

        return result

    def _build_context(self, query):
        context = []

        # Add long-term memory summary
        if self.long_term_memory:
            context.append(f"Previous context: {self.long_term_memory[-1]}")

        # Add recent interactions
        for interaction in self.short_term_memory:
            context.append(f"Q: {interaction['query']}")
            context.append(f"A: {interaction['result']}")

        # Add current query
        context.append(f"Q: {query}")

        return "\n".join(context)

    def _update_memory(self, query, result):
        # Add to short-term
        self.short_term_memory.append({
            'query': query,
            'result': result,
            'timestamp': time.time()
        })

        # If short-term full, summarize to long-term
        if len(self.short_term_memory) > self.memory_size:
            summary = self._summarize_memory()
            self.long_term_memory.append(summary)
            self.short_term_memory = []

    def _summarize_memory(self):
        interactions = "\n".join([
            f"Q: {m['query']}\nA: {m['result']}"
            for m in self.short_term_memory
        ])

        prompt = f"""
        Summarize these interactions into key facts:
        {interactions}
        """

        return self.llm(prompt)
```

## 🛡️ Error Handling & Retry

```python
from tenacity import retry, stop_after_attempt, wait_exponential

class RobustAgent:
    def __init__(self, llm, tools):
        self.llm = llm
        self.tools = tools

    @retry(
        stop=stop_after_attempt(3),
        wait=wait_exponential(multiplier=1, min=2, max=10)
    )
    def execute_tool(self, tool_name, args):
        """Execute with retry logic"""
        tool = self.tools.get(tool_name)

        if not tool:
            raise ValueError(f"Unknown tool: {tool_name}")

        try:
            result = tool(args)
            return {'success': True, 'result': result}
        except Exception as e:
            return {'success': False, 'error': str(e)}

    def run_with_fallback(self, query):
        try:
            return self.run(query)
        except Exception as e:
            # Fallback to simpler approach
            return self.llm(f"""
                I tried to solve this with tools but failed: {e}

                Query: {query}

                Provide best answer you can without tools.
            """)
```

## 📊 Agent Evaluation

```python
class AgentEvaluator:
    def evaluate(self, agent, test_cases):
        results = []

        for test in test_cases:
            start = time.time()

            try:
                answer = agent.run(test['query'])
                success = self._check_answer(answer, test['expected'])
                steps = len(agent.scratchpad)
            except Exception as e:
                answer = None
                success = False
                steps = 0

            elapsed = time.time() - start

            results.append({
                'query': test['query'],
                'answer': answer,
                'success': success,
                'steps': steps,
                'time': elapsed
            })

        return self._compute_metrics(results)

    def _compute_metrics(self, results):
        return {
            'accuracy': sum(r['success'] for r in results) / len(results),
            'avg_steps': np.mean([r['steps'] for r in results]),
            'avg_time': np.mean([r['time'] for r in results]),
            'success_rate': sum(r['answer'] is not None for r in results) / len(results)
        }
```

